// How long one live-speed poll may take before it is dropped.
const LIVE_SPEED_TIMEOUT_MS = 4000;

function LiveSpeed({ sessionId }) {
  // The label belongs to the mobile surface, not to a window width: it
  // appears whenever this device runs the mobile UI, at any viewport size.
  const store = useStore();
  const phone = store.phone;
  const [speed, setSpeed] = useState(null);
  useEffect(() => {
    allowFocusElement = null;
    currentSessionId = typeof sessionId === "string" && sessionId !== "" ? sessionId : null;
    return () => {
      if (currentSessionId === sessionId) currentSessionId = null;
    };
  }, [sessionId]);
  useEffect(() => {
    if (!sessionId || !phone) {
      setSpeed(null);
      return undefined;
    }
    let active = true;
    // One poll at a time. Starting one every 500 ms without waiting piles
    // them up on a slow link until they hold every connection the browser
    // allows to the host, and DSH Web's own requests stop getting through.
    let pending = null;
    const update = async () => {
      if (pending !== null) return;
      const controller = new AbortController();
      pending = controller;
      const giveUp = window.setTimeout(() => controller.abort(), LIVE_SPEED_TIMEOUT_MS);
      try {
        const response = await fetch(`/api/rdsh-mobile-ux/live-speed?sessionId=${encodeURIComponent(sessionId)}`, { cache: "no-store", signal: controller.signal });
        if (!response.ok) {
          if (active) setSpeed(null);
          return;
        }
        const data = await response.json();
        if (active) setSpeed(Number.isFinite(data?.tps) && data.tps > 0 ? Math.round(data.tps) : null);
      } catch {
        if (active) setSpeed(null);
      } finally {
        window.clearTimeout(giveUp);
        pending = null;
      }
    };
    void update();
    const timer = window.setInterval(() => void update(), 500);
    return () => {
      active = false;
      window.clearInterval(timer);
      pending?.abort();
    };
  }, [sessionId, phone]);
